"""Atlante 2.0 A3 — revisione densità (25/11/2026), iPhone 390x844. Uso: python3 tests/a32_test.py"""
import os, socket, threading, http.server, functools
from playwright.sync_api import sync_playwright
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
res = []
def ok(n, c, d=''):
    res.append(bool(c)); print(('PASS ' if c else 'FAIL ') + n + ((' ' + str(d)) if (d and not c) else ''))
class Q(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *a): pass
s = socket.socket(); s.bind(('127.0.0.1', 0)); port = s.getsockname()[1]; s.close()
srv = http.server.ThreadingHTTPServer(('127.0.0.1', port), functools.partial(Q, directory=ROOT)); threading.Thread(target=srv.serve_forever, daemon=True).start()
def boot(ctx):
    pg = ctx.new_page(); errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto('http://127.0.0.1:%d/index.html' % port); pg.wait_for_timeout(1200)
    pg.evaluate("()=>{journeyStarted.checked=true; journeyStarted.dispatchEvent(new Event('change',{bubbles:true}))}"); pg.wait_for_timeout(300)
    pg.evaluate("()=>document.getElementById('a2Entry').click()"); pg.wait_for_timeout(600)
    pg.evaluate("()=>document.querySelector('#atlas2 .a3-ban').click()"); pg.wait_for_timeout(1200)
    return pg, errs
J = lambda pg, e: pg.evaluate(e)
with sync_playwright() as p:
    br = p.chromium.launch(); ctx = br.new_context(viewport={'width': 390, 'height': 844}, is_mobile=True, has_touch=True, service_workers='block')
    pg, errs = boot(ctx)
    hh = J(pg, "()=>document.querySelector('#atlas2 .a3-hero').getBoundingClientRect().height")
    ok('Home: hero <= 335 px (-25% su 440)', hh <= 335, hh)
    J(pg, "()=>[...document.querySelectorAll('#atlas2 .btn')].find(b=>/Esplora il catalogo/.test(b.textContent)).click()"); pg.wait_for_timeout(1000)
    cols = lambda: J(pg, "()=>getComputedStyle(document.querySelector('#atlas2 .a3-grid')).gridTemplateColumns.split(' ').length")
    ok('vista predefinita compatta: Personaggi a 3 colonne', cols() == 3 and J(pg, "()=>!!document.querySelector('#atlas2 .a3-grid.c3')"), cols())
    ok('filtri richiusi di default', J(pg, "()=>document.querySelector('#atlas2 .a3-fpanel').hidden"))
    J(pg, "()=>document.querySelector('#atlas2 .a3-fbtn').click()"); ok('pannello filtri si apre', not J(pg, "()=>document.querySelector('#atlas2 .a3-fpanel').hidden"))
    sbh = J(pg, "()=>document.querySelector('#atlas2 .a3-in').getBoundingClientRect().height"); ok('barra di ricerca compatta (<= 38 px)', sbh <= 38, sbh)
    ok('testo schede >= 11 px', J(pg, "()=>[...document.querySelectorAll('#atlas2 .a3-tile .t b, #atlas2 .a3-tile .t span')].every(e=>parseFloat(getComputedStyle(e).fontSize)>=11)"))
    tw = J(pg, "()=>document.querySelector('#atlas2 .a3-tile').getBoundingClientRect().width"); ok('scheda personaggio <= 120 px di larghezza', tw <= 120, tw)
    ok('nessuna scheda sotto il launcher (gutter destro)', J(pg, "()=>{const g=document.querySelector('#atlas2 .a3-grid').getBoundingClientRect(); const t=[...document.querySelectorAll('#atlas2 .a3-tile')].reduce((m,e)=>Math.max(m,e.getBoundingClientRect().right),0); return t<=390-26}"))
    fab = J(pg, "()=>{const f=document.getElementById('mmFab'); if(!f) return null; const r=f.getBoundingClientRect(); return [r.left, r.width, r.height, getComputedStyle(f).display]}")
    ok('launcher Miss Minutes presente, linguetta >= 24x24 visibili', fab and fab[3] != 'none' and 23.5 <= (390 - fab[0]) <= 26 and fab[2] >= 24, fab)
    ok('launcher ancora cliccabile (non coperto)', J(pg, "()=>{const f=document.getElementById('mmFab'); const r=f.getBoundingClientRect(); const e=document.elementFromPoint(r.left+8, r.top+r.height/2); return e===f||f.contains(e)}"))
    J(pg, "()=>document.querySelector('#atlas2 .a3-seg button[aria-label=\"Elenco\"]').click()"); pg.wait_for_timeout(300)
    ok('modalità elenco memorizzata', J(pg, "()=>localStorage.getItem('tva-a3-vista')") == 'l')
    pg.close(); pg, errs = boot(ctx)
    J(pg, "()=>[...document.querySelectorAll('#atlas2 .btn')].find(b=>/Esplora il catalogo/.test(b.textContent)).click()"); pg.wait_for_timeout(900)
    ok('preferenza vista ripristinata dopo ricarico (elenco)', J(pg, "()=>document.querySelectorAll('#atlas2 .a3-li').length")>0 and J(pg, "()=>document.querySelectorAll('#atlas2 .a3-tile').length")==0)
    J(pg, "()=>document.querySelector('#atlas2 .a3-seg button[aria-label=\"Griglia grande\"]').click()"); pg.wait_for_timeout(300)
    ok('griglia grande: 2 colonne', cols() == 2)
    J(pg, "()=>document.querySelector('#atlas2 .a3-seg button[aria-label=\"Griglia compatta\"]').click()"); pg.wait_for_timeout(300)
    J(pg, "()=>[...document.querySelectorAll('#atlas2 .chip')].find(b=>b.textContent.indexOf('Universi')===0).click()"); pg.wait_for_timeout(800)
    ok('Universi: 2 colonne compatte', cols() == 2 and J(pg, "()=>!!document.querySelector('#atlas2 .a3-grid.c2')"), cols())
    em = J(pg, "()=>[...document.querySelectorAll('#atlas2 .a3-tile')].map(t=>[t.getAttribute('aria-label'), [...t.querySelectorAll('svg text')].map(x=>x.textContent).join('')])")
    d = dict(em)
    ok('Universi numerati: numero completo della Terra (199999, 121698, TRN123)', d.get('Earth-199999 — MCU') == '199999' and d.get('Earth-121698') == '121698' and d.get('Earth-TRN123') == 'TRN123', d)
    ok('Universi senza numero: nessuna sigla inventata, denominazione esistente nel titolo', d.get('Blade-verse') == '' and d.get('Marvel Zombies-verse') == '', d)
    J(pg, "()=>tvaA3.open('id-iron-man')"); pg.wait_for_timeout(1500)
    dh = J(pg, "()=>document.querySelector('#atlas2 .a3-dh').getBoundingClientRect().height"); ok('dossier: intestazione <= 235 px (era 330)', dh <= 235, dh)
    rb = J(pg, "()=>{const b=document.querySelector('#atlas2 .a3-ritbtn'); const r=b.getBoundingClientRect(); return [b.textContent.trim(), r.width, r.height, b.getAttribute('aria-label')]}")
    ok('Ritratto privato: icona 36x36 con etichetta accessibile', rb[0] == '' and rb[1] >= 36 and rb[2] >= 36 and 'Ritratto privato' in rb[3], rb)
    kvs = J(pg, "()=>[...document.querySelectorAll('#atlas2 #a3s-identita .a3-kv .k')].map(e=>e.textContent)")
    ok('dossier: «Universi: MCU» assorbito da «Universo: Earth-199999 — MCU» (un solo blocco)', kvs.count('Universo') == 1 and 'Universi' not in kvs, kvs)
    ok('dato originale intatto nel dossier JSON', 'Universi' in open(os.path.join(ROOT, 'atlante2/data/d/011.json'), encoding='utf-8').read())
    ok('nessun errore JS', not errs, errs)
    br.close()
print('\nA3.2-densita: %d / %d PASS' % (sum(res), len(res)))
raise SystemExit(0 if all(res) else 1)
